const $=s=>document.querySelector(s);
function range(id,label,min,max,value,step){return `<label class="row" for="${id}" style="margin-top:16px"><span>${label}</span><strong data-value="${id}">${value}</strong></label><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}">`}
export function renderLabs(main,speak){main.innerHTML=`<div class="eyebrow">PREDICT · EXPLORE · EXPLAIN</div><h1>先猜一猜，再動手驗證。</h1><p class="muted">改變一個條件，觀察結果，最後試著解釋為什麼。</p><div class="unit-grid"><section class="panel"><span class="tag">數學 · 二次函數</span><h2 style="margin-top:15px">讓函數的圖形動起來</h2><p class="muted">y＝a(x−h)²＋k。先預測頂點，再移動滑桿。</p>${range('quad-a','a：開口與寬窄',-3,3,1,.5)}${range('quad-h','h：水平位置',-4,4,0,1)}${range('quad-k','k：垂直位置',-4,4,0,1)}<div id="quad-plot"></div><div class="lab-output" id="quad-output" aria-live="polite"></div><a class="source-link" href="#/lesson/math-18">回到二次函數課程 →</a></section><section class="panel"><span class="tag">自然 · 電與電路</span><h2 style="margin-top:15px">固定電壓，改變電阻</h2><p class="muted">理想歐姆電阻模型。電阻加倍，電流會怎麼變？</p>${range('voltage','電壓 V（伏特）',1,24,12,1)}${range('resistance','電阻 R（歐姆）',1,24,6,1)}<div id="circuit-plot"></div><div class="lab-output" id="circuit-output" aria-live="polite"></div><p class="notice">只在虛擬模型中操作，不以家用插座做實驗。</p><a class="source-link" href="#/lesson/physics-7">回到電路課程 →</a></section><section class="panel"><span class="tag">自然 · 力矩平衡</span><h2 style="margin-top:15px">讓槓桿左右平衡</h2><p class="muted">左力×左力臂＝右力×右力臂。此圖比較力矩，不模擬旋轉過程。</p>${range('left-force','左側施力（N）',1,20,10,1)}${range('left-arm','左側力臂（cm）',10,100,40,10)}${range('right-force','右側施力（N）',1,20,10,1)}${range('right-arm','右側力臂（cm）',10,100,40,10)}<div id="lever-plot"></div><div class="lab-output" id="lever-output" aria-live="polite"></div><a class="source-link" href="#/lesson/physics-6">回到功與簡單機械 →</a></section><section class="panel"><span class="tag">英語 · 句型變化</span><h2 style="margin-top:15px">一句話，四種時間</h2><p class="muted">觀察主詞、動詞和時間語句一起改變。</p><div class="form-row"><label for="tense-person">主詞</label><select id="tense-person"><option>I</option><option>She</option><option>They</option></select></div><div class="form-row"><label for="tense-time">時態</label><select id="tense-time"><option value="present">現在簡單式</option><option value="progressive">現在進行式</option><option value="past">過去簡單式</option><option value="future">未來式</option></select></div><div class="lab-output" id="tense-output" aria-live="polite"></div><p id="tense-explanation" class="callout"></p><button id="tense-audio" class="button secondary">▷ 聽句子</button><a class="button ghost" href="#/lesson/english-1">回到句子骨架</a></section></div>`;main.querySelectorAll('input[type=range]').forEach(i=>i.oninput=()=>{document.querySelector(`[data-value="${i.id}"]`).textContent=i.value;update()});$('#tense-person').onchange=update;$('#tense-time').onchange=update;$('#tense-audio').onclick=()=>speak($('#tense-output').textContent);update()}
function update(){const num=id=>Number($('#'+id).value),a=num('quad-a'),h=num('quad-h'),k=num('quad-k'),toX=x=>200+x*23,toY=y=>140-y*15,points=[];for(let x=-8;x<=8;x+=.06){const y=a*(x-h)**2+k;points.push(`${toX(x).toFixed(1)},${toY(y).toFixed(1)}`)}let grid='';for(let i=-8;i<=8;i++)grid+=`<line x1="${toX(i)}" y1="5" x2="${toX(i)}" y2="275" stroke="#e3e9df"/>`;for(let j=-8;j<=8;j++)grid+=`<line x1="5" y1="${toY(j)}" x2="395" y2="${toY(j)}" stroke="#e3e9df"/>`;$('#quad-plot').innerHTML=`<svg class="lab-svg" viewBox="0 0 400 280" role="img" aria-label="函數圖形，每格一單位"><defs><clipPath id="plot-clip"><rect x="5" y="5" width="390" height="270"/></clipPath></defs>${grid}<path d="M5 140H395 M200 5V275" stroke="#80957e"/><text x="383" y="157" font-size="13">x</text><text x="209" y="17" font-size="13">y</text><text x="206" y="155" font-size="12">0</text><text x="313" y="155" font-size="12">5</text><text x="207" y="66" font-size="12">5</text><polyline clip-path="url(#plot-clip)" points="${points.join(' ')}" fill="none" stroke="#4e773b" stroke-width="3"/>${a!==0?`<circle cx="${toX(h)}" cy="${toY(k)}" r="5" fill="#203e31"/>`:''}</svg>`;$('#quad-output').textContent=a===0?`y＝${k}，是常數函數`:`頂點 (${h}, ${k}) · 開口向${a>0?'上':'下'}`;const v=num('voltage'),r=num('resistance');$('#circuit-output').textContent=`I＝${v} ÷ ${r}＝${(v/r).toFixed(2)} A`;$('#circuit-plot').innerHTML=`<svg class="lab-svg" viewBox="0 0 400 160" role="img" aria-label="電池和電阻形成閉合電路"><path d="M65 65V25H325V65 M325 100V135H65V85" fill="none" stroke="#50725f" stroke-width="3"/><path d="M45 65H85 M52 85H78" stroke="#264a36" stroke-width="4"/><rect x="310" y="65" width="30" height="35" fill="white" stroke="#264a36" stroke-width="3"/><text x="90" y="86" fill="#264a36" font-size="15">${v} V</text><text x="252" y="88" fill="#264a36" font-size="15">${r} Ω</text></svg>`;const lf=num('left-force'),la=num('left-arm'),rf=num('right-force'),ra=num('right-arm'),left=lf*la,right=rf*ra;$('#lever-output').textContent=`${left} : ${right} N·cm · ${left===right?'平衡':left>right?'左側力矩較大':'右側力矩較大'}`;$('#lever-plot').innerHTML=`<svg class="lab-svg" viewBox="0 0 400 120" role="img" aria-label="槓桿左右力臂與向下施力示意"><path d="M${200-la*1.7} 60H${200+ra*1.7} M190 80L200 60L210 80Z" fill="none" stroke="#52713f" stroke-width="4"/><path d="M${200-la*1.7} 10V50l-5 -7m5 7 5 -7 M${200+ra*1.7} 10V50l-5 -7m5 7 5 -7" fill="none" stroke="#44694b" stroke-width="2"/><text x="30" y="108" font-size="14">左 ${lf}N × ${la}cm</text><text x="238" y="108" font-size="14">右 ${rf}N × ${ra}cm</text></svg>`;const person=$('#tense-person').value,time=$('#tense-time').value,sentences={present:`${person} ${person==='She'?'plays':'play'} basketball every Sunday.`,progressive:`${person} ${person==='I'?'am':person==='She'?'is':'are'} playing basketball now.`,past:`${person} played basketball yesterday.`,future:`${person} will play basketball tomorrow.`};$('#tense-output').textContent=sentences[time];$('#tense-explanation').textContent={present:'描述習慣；She 是第三人稱單數，動詞加 s。',progressive:'be 動詞隨主詞變化，後面接 playing。',past:'描述昨天的事件；規則動詞 play 的過去式為 played。',future:'will 後面接原形 play，不隨主詞加 s。'}[time]}
